import {configured,rest,rpc,esc,brl,dateBR,localISO} from './api.js';
const $=s=>document.querySelector(s);let services=[],selectedTime='';const params=new URLSearchParams(location.search);const preset=params.get('servico');
const menu=$('#menu-btn'),links=$('#navlinks');menu?.addEventListener('click',()=>{const open=links.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});
$('#date').min=localISO();$('#date').value='';
function message(text,type='notice'){const box=$('#booking-message');box.innerHTML=`<div class="notice ${type}">${esc(text)}</div>`}
function selectedService(){return services.find(s=>s.id===$('#service').value)}
function updateSummary(){const s=selectedService();$('#summary-service').textContent=s?.name||'—';$('#summary-date').textContent=dateBR($('#date').value);$('#summary-time').textContent=selectedTime||'—';$('#summary-duration').textContent=s?`${s.duration_minutes} min`:'—';$('#summary-price').textContent=s?.price!=null?brl(s.price):'Sob consulta';$('#service-description').textContent=s?.description||''}
async function loadSlots(){selectedTime='';updateSummary();const s=selectedService(),date=$('#date').value;const box=$('#slots');if(!s||!date){box.innerHTML='<span class="muted" style="font-size:12px">Selecione um serviço e uma data.</span>';return}box.innerHTML='<span class="muted" style="font-size:12px">Consultando horários...</span>';try{const times=await rpc('available_slots',{p_service_id:s.id,p_date:date});box.innerHTML=times?.length?times.map(x=>`<button class="slot" type="button" data-time="${esc(x.slot_time.slice(0,5))}">${esc(x.slot_time.slice(0,5))}</button>`).join(''):'<span class="muted" style="font-size:12px">Não há horários disponíveis nesta data.</span>';box.querySelectorAll('.slot').forEach(b=>b.addEventListener('click',()=>{box.querySelectorAll('.slot').forEach(v=>v.classList.remove('active'));b.classList.add('active');selectedTime=b.dataset.time;updateSummary()}))}catch(e){box.innerHTML='<span class="muted" style="font-size:12px">Não foi possível consultar os horários.</span>';message(e.message,'error')}}
$('#service').addEventListener('change',loadSlots);$('#date').addEventListener('change',loadSlots);
if(!configured){$('#service').innerHTML='<option value="">Agendamento online indisponível</option>';$('#submit-booking').disabled=true;$('#submit-booking').style.opacity='.5';message('O agendamento online ainda não está conectado. Entre em contato pelo WhatsApp para solicitar seu horário.');}else{try{services=await rest('services','select=id,name,description,price,duration_minutes&active=eq.true&order=sort_order.asc');$('#service').innerHTML='<option value="">Selecione um serviço</option>'+services.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');if(preset&&services.some(s=>s.id===preset)){$('#service').value=preset;updateSummary()}}catch(e){message('Não foi possível carregar os serviços. Tente novamente ou fale conosco pelo WhatsApp.','error');$('#submit-booking').disabled=true}}
$('#booking-form').addEventListener('submit',async e=>{e.preventDefault();const s=selectedService(),date=$('#date').value,name=$('#name').value.trim(),phone=$('#phone').value.replace(/\D/g,''),address=$('#address').value.trim();if(!s||!date||!selectedTime){message('Selecione serviço, data e horário.','error');return}if(phone.length<10||phone.length>13){message('Informe um telefone válido com DDD.','error');return}if(name.length<3||address.length<10){message('Confira seu nome e endereço.','error');return}const button=$('#submit-booking');button.disabled=true;button.textContent='Registrando...';try{await rpc('book_appointment',{p_service_id:s.id,p_date:date,p_time:selectedTime,p_name:name,p_phone:phone,p_address:address,p_notes:$('#notes').value.trim(),p_consent:true,p_whatsapp_opt_in:$('#whatsapp-opt-in').checked});const msg=`Olá! Meu agendamento na Prime Lava Car JP foi recebido. Nome: ${name}. Serviço: ${s.name}. Data: ${dateBR(date)} às ${selectedTime}. Endereço: ${address}.`;const link=`https://wa.me/5583986201295?text=${encodeURIComponent(msg)}`;$('#booking-form').innerHTML=`<div class="eyebrow">Solicitação recebida</div><h2 style="margin-top:18px">Agendamento registrado.</h2><p>Recebemos seu pedido para ${esc(s.name)} em ${esc(dateBR(date))} às ${esc(selectedTime)}. Nossa equipe acompanhará a solicitação. Para falar conosco agora, abra a conversa no WhatsApp.</p><div class="notice success">Se a confirmação automática estiver ativa e você autorizou o contato, ela será enviada por WhatsApp. Você também pode iniciar uma conversa pelo botão abaixo.</div><a class="btn btn-red" style="margin-top:20px" href="${link}" target="_blank" rel="noopener">Abrir WhatsApp ↗</a>`}catch(err){message(err.message.includes('conflict')||err.message.includes('horário')?'Este horário acabou de ficar indisponível. Escolha outro.':err.message,'error');await loadSlots()}finally{button.disabled=false;button.innerHTML='Confirmar solicitação <span class="arrow">↗</span>'}});
